import{_ as o,o as e,c as n,aj as a}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/introduction/introductions.md","filePath":"1.0/introduction/introductions.md","lastUpdated":1785836850000}'),r={name:"1.0/introduction/introductions.md"};function s(i,t,u,p,d,c){return e(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> is an open-source Product Information Management (PIM) system built on the Laravel framework. It helps businesses organize, manage, and enrich their product information in one central repository.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><p><strong>1) Centralized Product Management-</strong> Manage all your product data at one place.</p><p><strong>2) Data Enrichment-</strong> Enhance your product information with detailed attributes.</p><p><strong>3) Category Management-</strong> Organize products into categories for easier navigation, with customizable category fields.</p><p><strong>4) User Management-</strong> Control user access and permissions.</p><p><strong>5) API Integration-</strong> Seamlessly integrate with other systems via RESTful APIs.</p><p><strong>6) Localization-</strong> Support for multiple languages and locales.</p><p><strong>7) Import/Export Functionality-</strong> Easily import and export product data using CSV and XLSX formats, with a quick export feature for streamlined data handling.</p><p><strong>8) Magic AI for Product Content Generation-</strong> Automatically generate engaging product content using advanced LLM (Large Language Model) technology.</p><p><strong>9) Multi-Channel Support-</strong> Manage and distribute your product data across multiple sales channels from a single platform.</p><p><strong>10) Product Completeness Evaluation-</strong> Measure and improve product data quality using completeness scores and rules.</p><p><strong>11) Product Bulk Edit-</strong> Update multiple products simultaneously with advanced bulk-editing tools.</p><p><strong>12) Webhooks &amp; Integrations-</strong> React to real-time product updates using configurable webhooks.</p><p><strong>13) Dynamic Product Datagrid-</strong> Customize product grids with dynamic columns, filters, and improved performance.</p><p><strong>14) Media &amp; Video Support-</strong> Manage images and videos directly within gallery attributes.</p><p><strong>15) Cross-Database Compatibility-</strong> Run UnoPim with MySQL, MariaDB, or PostgreSQL support.</p><p><strong>16) Scalable Job &amp; Queue Processing-</strong> Execute long-running jobs efficiently using system and default queues.</p>',19)])])}const m=o(r,[["render",s]]);export{g as __pageData,m as default};
